// MPCompatibility_AC.h// Copyright © 2000-2001 by Apple Computer, Inc. All rights reserved. // Provides compatibility with the different versions of Multiprocessing.h in// the 3.2 and 3.3 Universal Interfaces. It is not possible to directly check// the MP API version at compile time. The best we can do is assume that, if you // have the 3.2 interfaces or earlier, you are using version 1.4 of the MP APIs. // If you have the 3.3 interfaces or later, we assume you have version 2.0 or // later of the MP APIs. This means, if you install the MP 2.0 or 2.1 SDK over // the 3.2 interfaces, we will break. The best approach is to use the 3.2 // interfaces as they are, and to upgrade to the latest interfaces before// installing the latest MP SDK. /*	Change History:		02/14/01	Don't include Threads_AC. 		01/02/01	Update copyright.		04/25/00	Rename MultiprocessingSupport_AC to MPCompatibility_AC. 							kDurationImmediate and kDurationForever should not							be defined here. 							Include thread switches and conditionalize on qWantsMP. 		04/19/00	new today. */ #ifndef __MPCompatibility_AC__#define	__MPCompatibility_AC__// Switches#ifndef __Types_AC__#include "Types_AC.h"#endif#if qWantsMP// Toolbox#ifndef __MULTIPROCESSING__#include <Multiprocessing.h>#endif//----------------------------------------------------------------------------------------// Constants//----------------------------------------------------------------------------------------#if UNIVERSAL_INTERFACES_VERSION < 0x0330typedef UInt8 							MPRemoteContext;enum {	kMPAnyRemoteContext			= 0,	kMPOwningProcessRemoteContext = 1};#endif // UNIVERSAL_INTERFACES_VERSION < 0x0330// We really want to test against the version of the MP APIs. Unfortunately, the version// information in Multiprocessing.h is available only as a string symbol or an enum, // neither of which can be tested at compile time. As a workaround, we test against the// version of the Universal Interfaces. //#if (MP_API_Version == "1.4")#if UNIVERSAL_INTERFACES_VERSION < 0x0330#if TARGET_CPU_PPC// Multiprocessing.h only allows access to this for PPC builds//----------------------------------------------------------------------------------------// MPTaskIsPreemptive//----------------------------------------------------------------------------------------inline bool MPTaskIsPreemptive(MPTaskID taskID){	return !MPTaskIsToolboxSafe(taskID);}//----------------------------------------------------------------------------------------// MPRemoteCall//----------------------------------------------------------------------------------------inline void* MPRemoteCall(MPRemoteProcedure remoteProc,						  void* parameter,						  MPRemoteContext context){#pragma unused (context)	return MPRPC(remoteProc, parameter);}#endif // TARGET_CPU_PPC#endif // UNIVERSAL_INTERFACES_VERSION < 0x0330#endif // qWantsMP#endif // __MPCompatibility_AC__